import { computed, defineAsyncComponent, defineComponent, getCurrentInstance, h } from 'vue'

import type { AppContext, Component, PropType, SlotsType } from 'vue'
import { MarkdownDocument } from '@comark/vue'
import { pascalCase } from '@comark/vue/utils'
import type { MarkdownDocumentProps } from '@comark/vue'
import type { MarkdownDocument as ComarkMarkdownDocument } from 'comark'

// Generated by the module: the component each tag renders with, keyed by the tag in PascalCase.
// Virtual imports have to be static for the bundler to rewrite them; the file only exists in a Nuxt build.
import { components as contentComponents } from '#build/content/components.mjs'

type MarkdownDocumentValue = NonNullable<MarkdownDocumentProps['value']>
/** Handling both v3 and v4 content documents. */
type ContentDocumentValue = { body: { value: MarkdownDocumentValue['nodes'] } | MarkdownDocumentValue['nodes'] } & Record<string, any>

function isMarkdownDocument(value: MarkdownDocumentValue | ContentDocumentValue): value is MarkdownDocumentValue {
  return 'nodes' in value
}

const debug = import.meta.dev || (import.meta as { preview?: boolean }).preview

/** A component, a lazy loader, or the name of a global component registered on the app. */
type ContentComponent = Component | string | (() => Promise<Component | { default: Component }>)

// Lazy entries are generated as `async () => import(...)`. A plain function can't be the
// marker: functional components (e.g. from a `.ts` file) are plain functions too.
function isLazyLoader(component: ContentComponent): component is () => Promise<unknown> {
  return Object.prototype.toString.call(component) === '[object AsyncFunction]'
}

const asyncWrappedComponents = new WeakMap<object, Component>()

/**
 * Components with a `setup` are wrapped in an async component (cached per component),
 * so an async `setup` resolves the same way as a lazy one.
 */
function wrapComponent(component: Component): Component {
  if (typeof component !== 'object' || '__asyncLoader' in component || !('setup' in component)) {
    return component
  }
  let wrapped = asyncWrappedComponents.get(component)
  if (!wrapped) {
    wrapped = defineAsyncComponent(() => Promise.resolve(component))
    asyncWrappedComponents.set(component, wrapped)
  }
  return wrapped
}

/** `foo`, `Foo` and `ProseFoo` all key the component of the tag `foo`. */
function componentKey(name: string) {
  return pascalCase(name).replace(/^Prose(?=[A-Z])/, '')
}

// Resolved once per app: global entries are looked up on its registered components.
const resolvedComponents = new WeakMap<AppContext, Record<string, Component>>()
const asyncLoadedComponents = new Map<string, Component>()

function resolveContentComponents(appContext: AppContext | undefined): Record<string, Component> {
  const cached = appContext && resolvedComponents.get(appContext)
  if (cached) return cached
  const resolved: Record<string, Component> = {}
  for (const [key, entry] of Object.entries(contentComponents as Record<string, ContentComponent>)) {
    if (typeof entry === 'string') {
      const component = appContext?.components[entry]
      if (component) resolved[key] = wrapComponent(component)
    }
    else if (isLazyLoader(entry)) {
      // Cached so each loads once.
      let component = asyncLoadedComponents.get(key)
      if (!component) {
        component = defineAsyncComponent(entry as () => Promise<Component>)
        asyncLoadedComponents.set(key, component)
      }
      resolved[key] = component
    }
    else {
      resolved[key] = wrapComponent(entry)
    }
  }
  if (appContext) resolvedComponents.set(appContext, resolved)
  return resolved
}

/**
 * Components passed to `MarkdownDocument`: the generated map, overridden by the `components`
 * prop. They're passed as `components`, which `MarkdownDocument` checks before the app's global
 * components, so the winner the module picked for each tag is the one rendered.
 */
function resolveComponentsMap(components: Record<string, unknown> = {}) {
  // Must run during render: the global entries are read from the current instance's app.
  const appContext = getCurrentInstance()?.appContext
  const resolved = resolveContentComponents(appContext)
  // `{ foo: … }` replaces the generated entry of `foo`.
  const overridden = new Set(Object.keys(components).map(componentKey))
  const result: Record<string, unknown> = Object.fromEntries(Object.entries(resolved).filter(([key]) => !overridden.has(key)))
  for (const [tag, component] of Object.entries(components)) {
    // Values can be component names (`{ p: 'MyParagraph' }`), resolved like tags, then as global
    // components. Unknown names (e.g. another HTML tag such as `'div'`) are rendered as-is.
    result[tag] = typeof component === 'string'
      ? resolved[componentKey(component)] ?? appContext?.components[component] ?? component
      : component
  }
  return result as MarkdownDocumentProps['components']
}

export default defineComponent({
  name: 'ContentDocument',
  props: {
    /**
     * Content to render: a Comark document (`{ nodes, frontmatter, meta }`) or a
     * document returned by `queryCollection()` (`{ body, ...frontmatter }`).
     */
    value: {
      type: Object as PropType<MarkdownDocumentValue | ContentDocumentValue>,
      default: undefined,
    },
    /**
     * Custom component mappings for element tags
     */
    components: {
      type: Object as PropType<MarkdownDocumentProps['components']>,
      default: undefined,
    },
    /**
     * Additional data made available to the rendered tree (e.g. for binding
     * frontmatter/props).
     */
    data: {
      type: Object as PropType<MarkdownDocumentProps['data']>,
      default: undefined,
    },
  },
  slots: Object as SlotsType<{
    empty?: (props: { 'data-content-id': string | undefined }) => unknown
  }>,
  setup(props, { slots }) {
    const comarkTree = computed(() => {
      if (!props.value) return undefined
      if (isMarkdownDocument(props.value)) return props.value
      const { body, id, path, ...rest } = props.value
      return {
        path,
        // Handling compatibility with v3 documents.
        nodes: Array.isArray(body) ? body : body.value,
        frontmatter: rest,
        meta: {
          id,
        },
      }
    })
    const isEmpty = computed(() => !comarkTree.value)

    return () => {
      const dataContentId = debug
        ? (comarkTree.value as ComarkMarkdownDocument)?.meta?.key
        : undefined

      if (isEmpty.value) {
        return slots.empty?.({ 'data-content-id': dataContentId }) ?? null
      }

      return h(MarkdownDocument, {
        'value': comarkTree.value!,
        'components': resolveComponentsMap(props.components),
        'data': props.data,
        'data-content-id': dataContentId,
      })
    }
  },
})
